// dynasties.betterbukidnon.org: every elected official in Bukidnon since 2001 and the
// documented family ties between them.
//
//   data/officials.json  generated by scripts/build-data.mjs from OpenHalalan (ODbL)
//   data/families.json   curated by hand; every tie cites a published source
//
// Hash routes: #/ (mayors) · #/place/{id} · #/province · #/families · #/family/{id}
//              #/officials · #/person/{id} · #/about

(function () {
  'use strict';

  const I18N = window.DYI18N;
  const t = (key, fallback, params) => (I18N ? I18N.t(key, fallback, params) : fallback);

  const POS_LABEL = {
    governor: ['dy-pos-governor', 'Governor'],
    'vice-governor': ['dy-pos-vice-governor', 'Vice Governor'],
    representative: ['dy-pos-representative', 'House Representative'],
    'board-member': ['dy-pos-board-member', 'Provincial Board Member'],
    mayor: ['dy-pos-mayor', 'Mayor'],
    'vice-mayor': ['dy-pos-vice-mayor', 'Vice Mayor'],
    councilor: ['dy-pos-councilor', 'Councilor'],
  };
  const posLabel = (p) => t(...POS_LABEL[p]);
  const TERM = 3;
  const LATEST_NOTE = 'latest';

  let D; // officials.json
  let F; // families.json
  const idx = {};

  // ---------- Helpers ----------

  const $ = (sel) => document.querySelector(sel);
  const esc = (s) =>
    String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const fold = (s) =>
    String(s)
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .toLowerCase();

  // Election years → "2007–2013, 2022–2028" (each term runs three years)
  function spans(years) {
    const ys = [...new Set(years)].sort((a, b) => a - b);
    const out = [];
    for (const y of ys) {
      const last = out.at(-1);
      if (last && y === last[1]) last[1] = y + TERM;
      else out.push([y, y + TERM]);
    }
    return out.map(([a, b]) => `${a}–${b}`).join(', ');
  }

  const placeName = (id) => idx.place[id]?.name ?? id;
  const personLink = (id, cls = 'dy-person') => {
    const p = idx.person[id];
    const dot = idx.tiesOf[id]?.length ? '<span class="dy-dot" aria-hidden="true"></span>' : '';
    return `${dot}<a class="${cls}" href="#/person/${esc(id)}">${esc(p.name)}</a>`;
  };
  const extLink = (url, text) => `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(text)} <span aria-hidden="true">↗</span></a>`;

  // "Mayor of Lantapan (2007–2016)" lines for one person
  function officeLines(personId) {
    const groups = new Map();
    for (const tm of idx.termsOf[personId] ?? []) {
      const k = `${tm.position}|${tm.place ?? ''}`;
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(tm.year);
    }
    const order = Object.keys(POS_LABEL);
    return [...groups]
      .sort((a, b) => order.indexOf(a[0].split('|')[0]) - order.indexOf(b[0].split('|')[0]))
      .map(([k, years]) => {
        const [pos, place] = k.split('|');
        const where = place ? `, ${placeName(place)}` : '';
        return `${posLabel(pos)}${where} (${spans(years)})`;
      });
  }

  // Families and ties a member key belongs to. Keys are person ids from officials.json,
  // or "x-…" for relatives outside it (e.g. a senator).
  function memberName(fam, key) {
    const m = fam.members.find((m) => m.key === key);
    return m?.person ? idx.person[m.person]?.name ?? m.name : m?.name ?? key;
  }

  // ---------- Data ----------

  function buildIndex() {
    idx.place = Object.fromEntries(D.places.map((p) => [p.id, p]));
    idx.person = Object.fromEntries(D.people.map((p) => [p.id, p]));
    idx.fix = Object.fromEntries(D.fixes.map((f) => [f.id, f]));
    idx.termsOf = {};
    for (const tm of D.terms) (idx.termsOf[tm.person] ??= []).push(tm);
    idx.family = Object.fromEntries(F.families.map((f) => [f.id, f]));
    idx.familiesOf = {};
    idx.tiesOf = {}; // person id → [{fam, tie, other, role}]
    let ties = 0;
    for (const fam of F.families) {
      for (const m of fam.members) if (m.person) (idx.familiesOf[m.person] ??= new Set()).add(fam.id);
      for (const tie of fam.ties) {
        ties++;
        const pa = fam.members.find((m) => m.key === tie.a)?.person;
        const pb = fam.members.find((m) => m.key === tie.b)?.person;
        // On A's page the relative is B, described by B's role ("son"), and vice versa.
        if (pa) (idx.tiesOf[pa] ??= []).push({ fam, tie, other: tie.b, role: tie.bIs });
        if (pb) (idx.tiesOf[pb] ??= []).push({ fam, tie, other: tie.a, role: tie.aIs });
      }
    }
    idx.tieCount = ties;
    idx.latest = D.years.at(-1);
  }

  // Runs of consecutive terms in one seat: [{person, years}] or [{gap: year}]
  function seatRuns(place, position) {
    const out = [];
    for (const y of D.years) {
      const tms = D.terms.filter((tm) => tm.place === place && tm.position === position && tm.year === y);
      const last = out.at(-1);
      if (!tms.length) {
        if (last?.gap) last.years.push(y);
        else out.push({ gap: true, years: [y] });
        continue;
      }
      const pid = tms[0].person;
      if (last && last.person === pid) last.years.push(y);
      else out.push({ person: pid, years: [y] });
    }
    return out;
  }

  // ---------- Views: Mayors ----------

  function renderMayors() {
    $('#stat-people').textContent = D.people.length.toLocaleString();
    $('#stat-families').textContent = F.families.length;
    $('#stat-ties').textContent = idx.tieCount;
    const latestMayors = D.terms.filter((tm) => tm.position === 'mayor' && tm.year === idx.latest);
    const tied = latestMayors.filter((tm) => idx.tiesOf[tm.person]?.length).length;
    $('#stat-tied').textContent = `${tied} / ${D.places.length}`;

    const q = fold($('#m-search').value.trim());
    const district = $('#m-district').value;
    const onlyTied = $('#m-tied').checked;
    const rows = [];
    for (const place of D.places) {
      if (district && place.district !== district) continue;
      const runs = seatRuns(place.id, 'mayor');
      const mayors = runs.filter((r) => r.person).map((r) => r.person);
      const familyIds = new Set(mayors.flatMap((pid) => [...(idx.familiesOf[pid] ?? [])]));
      if (onlyTied && !familyIds.size) continue;
      if (q && !fold(place.name).includes(q) && !mayors.some((pid) => fold(idx.person[pid].name).includes(q))) continue;

      const runHtml = runs
        .slice()
        .reverse()
        .map((r) =>
          r.gap
            ? `<li><span class="dy-years">${r.years.join(', ')}</span><span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span></li>`
            : `<li><span class="dy-years">${spans(r.years)}</span><span>${personLink(r.person)}</span></li>`,
        )
        .join('');

      const ties = mayors
        .flatMap((pid) => (idx.tiesOf[pid] ?? []).map((x) => ({ pid, ...x })))
        .filter((x, i, all) => all.findIndex((y) => y.pid === x.pid && y.other === x.other) === i);
      const tieHtml = ties.length
        ? `<ul class="dy-runs">${ties
            .slice(0, 6)
            .map(
              (x) =>
                `<li style="grid-template-columns:minmax(0,1fr)"><span>${esc(idx.person[x.pid].name)}: <span class="dy-tie-role">${esc(roleLabel(x.role))}</span> ${esc(memberName(x.fam, x.other))}</span></li>`,
            )
            .join('')}${ties.length > 6 ? `<li style="grid-template-columns:minmax(0,1fr)"><a href="#/place/${place.id}">${esc(t('dy-more', '+{n} more', { n: ties.length - 6 }))}</a></li>` : ''}</ul>
           <div class="dy-chips" style="margin-top:6px">${[...familyIds].map((f) => familyChip(f)).join('')}</div>`
        : `<span class="dy-none">${esc(t('dy-no-ties', 'None documented yet'))}</span>`;

      rows.push(`<tr>
        <td><a class="dy-person" href="#/place/${place.id}">${esc(place.name)}</a>
          <span class="dy-sub">${esc(t('dy-district-n', '{d} district', { d: place.district }))}</span></td>
        <td><ul class="dy-runs">${runHtml}</ul></td>
        <td>${tieHtml}</td>
      </tr>`);
    }
    $('#mayor-rows').innerHTML = rows.join('');
    $('#mayor-empty').hidden = rows.length > 0;
  }

  const familyChip = (fid) => `<a class="dy-chip" href="#/family/${esc(fid)}">${esc(idx.family[fid].name)}</a>`;

  const ROLES = {
    father: 'Father', mother: 'Mother', son: 'Son', daughter: 'Daughter', child: 'Child', parent: 'Parent',
    husband: 'Husband', wife: 'Wife', spouse: 'Spouse', brother: 'Brother', sister: 'Sister', sibling: 'Sibling',
    grandfather: 'Grandfather', grandmother: 'Grandmother', grandson: 'Grandson', granddaughter: 'Granddaughter',
    uncle: 'Uncle', aunt: 'Aunt', nephew: 'Nephew', niece: 'Niece', cousin: 'Cousin',
    'father-in-law': 'Father-in-law', 'mother-in-law': 'Mother-in-law', 'son-in-law': 'Son-in-law',
    'daughter-in-law': 'Daughter-in-law', 'brother-in-law': 'Brother-in-law', 'sister-in-law': 'Sister-in-law', relative: 'Relative',
  };
  const roleLabel = (r) => t(`dy-role-${r}`, ROLES[r] ?? r);

  // ---------- Views: Place ----------

  function renderPlace(id) {
    const place = idx.place[id];
    if (!place) return notFound();
    const at = (pos, y) => D.terms.filter((tm) => tm.place === id && tm.position === pos && tm.year === y);
    const latest = idx.latest;
    const cur = (pos) => at(pos, latest).map((tm) => personLink(tm.person)).join(', ') || `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`;

    const byYear = D.years
      .slice()
      .reverse()
      .map((y) => {
        const m = at('mayor', y);
        const v = at('vice-mayor', y);
        const c = at('councilor', y);
        const gap = `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`;
        return `<tr>
          <td class="dy-year">${y}</td>
          <td>${m.map((tm) => personLink(tm.person)).join(', ') || gap}</td>
          <td>${v.map((tm) => personLink(tm.person)).join(', ') || gap}</td>
          <td class="dy-hide-sm"><div class="dy-councils">${c.map((tm) => `<span>${personLink(tm.person)}</span>`).join('') || gap}</div></td>
        </tr>`;
      })
      .join('');

    // Families with any member holding office here
    const here = new Set(D.terms.filter((tm) => tm.place === id).map((tm) => tm.person));
    const fams = F.families.filter((f) => f.members.some((m) => m.person && here.has(m.person)) || (f.places ?? []).includes(id));
    const tieItems = [...here]
      .flatMap((pid) => (idx.tiesOf[pid] ?? []).map((x) => ({ pid, ...x })))
      .filter((x, i, all) => all.findIndex((y) => y.tie === x.tie) === i);

    const fixes = [...new Set(D.terms.filter((tm) => tm.place === id && tm.fix).map((tm) => tm.fix))];
    const unplaced = D.terms.filter((tm) => !tm.place && tm.placeCandidates?.includes(id));

    $('#place-body').innerHTML = `
      <p class="dy-crumbs"><a href="#/">${esc(t('dy-nav-mayors', 'Mayors'))}</a> / ${esc(t('dy-district-n', '{d} district', { d: place.district }))}</p>
      <h1 class="dy-h1">${esc(place.name)}</h1>
      <p class="dy-lede">${esc(
        place.type === 'city'
          ? t('dy-place-city', 'Component city, {d} congressional district of Bukidnon.', { d: place.district })
          : t('dy-place-mun', 'Municipality, {d} congressional district of Bukidnon.', { d: place.district }),
      )}</p>

      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-current', 'Elected in {y}', { y: latest }))}</h2>
        <table class="dy-table"><tbody>
          <tr><td class="dy-pos">${esc(posLabel('mayor'))}</td><td>${cur('mayor')}</td></tr>
          <tr><td class="dy-pos">${esc(posLabel('vice-mayor'))}</td><td>${cur('vice-mayor')}</td></tr>
          <tr><td class="dy-pos">${esc(t('dy-pos-councilors', 'Councilors'))}</td><td><div class="dy-councils">${at('councilor', latest)
            .map((tm) => `<span>${personLink(tm.person)}</span>`)
            .join('')}</div></td></tr>
        </tbody></table>
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-ties-here', 'Documented family ties'))}</h2>
        ${
          tieItems.length
            ? `<ul class="dy-ties">${tieItems.map((x) => tieItem(x.fam, x.tie)).join('')}</ul><div class="dy-chips" style="margin-top:10px">${fams.map((f) => familyChip(f.id)).join('')}</div>`
            : `<p class="dy-none">${esc(t('dy-no-ties-place', 'No family ties documented for officials here yet. If you know of one with a published source, report it.'))}</p>`
        }
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-by-election', 'Winners by election'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr>
            <th scope="col">${esc(t('dy-col-year', 'Year'))}</th>
            <th scope="col">${esc(posLabel('mayor'))}</th>
            <th scope="col">${esc(posLabel('vice-mayor'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-pos-councilors', 'Councilors'))}</th>
          </tr></thead>
          <tbody>${byYear}</tbody>
        </table></div>
        ${fixes.map((f) => `<p class="dy-note">${esc(t('dy-fix-note', 'Corrected:'))} ${esc(idx.fix[f].reason)}</p>`).join('')}
        ${
          unplaced.length
            ? `<p class="dy-note">${esc(
                t('dy-unplaced-note', 'These winners are filed under the wrong place in the source and could not be placed with certainty. They belong to {places}:', {
                  places: [...new Set(unplaced.flatMap((tm) => tm.placeCandidates))].map(placeName).join(' or '),
                }),
              )} ${unplaced.map((tm) => `${personLink(tm.person)} (${tm.year} ${esc(posLabel(tm.position))})`).join(', ')}</p>`
            : ''
        }
      </section>`;
  }

  // One documented tie, with its sources
  function tieItem(fam, tie, perspective) {
    const a = memberName(fam, tie.a);
    const b = memberName(fam, tie.b);
    const link = (key, name) => {
      const pid = fam.members.find((m) => m.key === key)?.person;
      return pid ? `<a class="dy-person" href="#/person/${esc(pid)}">${esc(name)}</a>` : `<strong>${esc(name)}</strong>`;
    };
    // Translate the sentence with placeholders, escape it, then put the links in.
    const tpl =
      tie.aIs === 'relative'
        ? t('dy-tie-related', '{a} and {b} are related.', { a: '@@A@@', b: '@@B@@' })
        : t('dy-tie-sentence', '{a} is the {role} of {b}.', { a: '@@A@@', role: roleLabel(tie.aIs).toLowerCase(), b: '@@B@@' });
    const sentence = esc(tpl).replace('@@A@@', link(tie.a, a)).replace('@@B@@', link(tie.b, b));
    return `<li>
      <span class="dy-tie-role">${esc(familyLabel(fam))}</span>
      <span class="dy-tie-who">${sentence}</span>
      ${tie.note ? `<p class="dy-note">${esc(tie.note)}</p>` : ''}
      ${sourcesHtml(tie.sources)}
    </li>`;
  }

  const familyLabel = (fam) => t('dy-family-of', '{name} family', { name: fam.name });

  function sourcesHtml(sources) {
    if (!sources?.length) return '';
    const quotes = sources.filter((s) => s.quote);
    return `${quotes.map((s) => `<p class="dy-quote">“${esc(s.quote)}” <span class="dy-count">${esc(s.publisher)}</span></p>`).join('')}<div class="dy-cite"><span class="dy-cite-label">${esc(
      t('dy-sources', 'Sources'),
    )}</span>${sources.map((s) => extLink(s.url, [s.publisher, s.date].filter(Boolean).join(', ') || s.title)).join('')}</div>`;
  }

  // ---------- Views: Province ----------

  function renderProvince() {
    const rowsFor = (positions) =>
      D.years
        .slice()
        .reverse()
        .map((y) => {
          const cells = positions.map((pos) => {
            const tms = D.terms.filter((tm) => tm.position === pos && tm.year === y);
            const list = tms.map((tm) => `<span>${personLink(tm.person)}</span>`).join('');
            return `<td><div class="dy-councils">${list || `<span class="dy-gap">${esc(t('dy-gap', 'Not in the source data'))}</span>`}</div></td>`;
          });
          return `<tr><td class="dy-year">${y}</td>${cells.join('')}</tr>`;
        })
        .join('');
    $('#province-body').innerHTML = `
      <h1 class="dy-h1">${esc(t('dy-nav-province', 'Province'))}</h1>
      <p class="dy-lede">${esc(t('dy-province-desc', 'Governors, vice governors, House representatives and provincial board members elected in Bukidnon since 2001.'))}</p>
      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-gov-vg', 'Governor and vice governor'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(posLabel('governor'))}</th><th scope="col">${esc(posLabel('vice-governor'))}</th></tr></thead>
          <tbody>${rowsFor(['governor', 'vice-governor'])}</tbody></table></div>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-reps', 'House representatives'))}</h2>
        <p class="dy-block-sub">${esc(t('dy-reps-note', 'Bukidnon had three districts until 2013 and four since. The source does not say which district each representative won.'))}</p>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(t('dy-reps', 'House representatives'))}</th></tr></thead>
          <tbody>${rowsFor(['representative'])}</tbody></table></div>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-board', 'Provincial board (Sangguniang Panlalawigan)'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-year', 'Year'))}</th><th scope="col">${esc(t('dy-board-members', 'Elected board members'))}</th></tr></thead>
          <tbody>${rowsFor(['board-member'])}</tbody></table></div>
      </section>`;
  }

  // ---------- Views: Families ----------

  function renderFamilies() {
    const fams = F.families.slice().sort((a, b) => b.members.length - a.members.length || a.name.localeCompare(b.name));
    $('#families-body').innerHTML = `
      <h1 class="dy-h1">${esc(t('dy-nav-families', 'Families'))}</h1>
      <p class="dy-lede">${esc(t('dy-families-desc', 'Families with two or more members who held elected office, where a published source states how they are related.'))}</p>
      <p class="dy-note dy-note-plain">${esc(F.note)}</p>
      <div class="dy-grid" style="margin-top:24px">${fams
        .map((f) => {
          const inOffice = f.members.filter((m) => m.person && (idx.termsOf[m.person] ?? []).some((tm) => tm.year === idx.latest)).length;
          const places = [...new Set(f.members.flatMap((m) => (m.person ? (idx.termsOf[m.person] ?? []).map((tm) => tm.place).filter(Boolean) : [])))];
          return `<article class="dy-card">
            <span class="dy-label">${esc(t('dy-n-members', '{n} members · {k} ties', { n: f.members.length, k: f.ties.length }))}</span>
            <h3><a href="#/family/${esc(f.id)}">${esc(familyLabel(f))}</a></h3>
            <p>${esc(f.summary)}</p>
            <div class="dy-card-meta">
              <span class="dy-count">${esc(t('dy-in-office', '{n} elected in {y}', { n: inOffice, y: idx.latest }))}</span>
              ${places.length ? `<span class="dy-count">${esc(places.map(placeName).join(', '))}</span>` : ''}
            </div>
          </article>`;
        })
        .join('')}</div>`;
  }

  function renderFamily(id) {
    const fam = idx.family[id];
    if (!fam) return notFound();
    const members = fam.members
      .map((m) => {
        const lines = [...(m.person ? officeLines(m.person) : []), ...(m.offices ?? [])];
        const name = m.person ? personLink(m.person) : `<strong>${esc(m.name)}</strong>`;
        return `<tr><td>${name}${m.note ? `<span class="dy-sub">${esc(m.note)}</span>` : ''}</td><td>${lines.map(esc).join('<br>') || `<span class="dy-none">${esc(t('dy-no-office', 'No elected office on record'))}</span>`}</td></tr>`;
      })
      .join('');
    $('#family-body').innerHTML = `
      <p class="dy-crumbs"><a href="#/families">${esc(t('dy-nav-families', 'Families'))}</a></p>
      <h1 class="dy-h1">${esc(familyLabel(fam))}</h1>
      <p class="dy-lede">${esc(fam.summary)}</p>
      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-diagram', 'How they are related'))}</h2>
        <div class="dy-diagram">${diagram(fam)}</div>
        <p class="dy-legend"><span>── ${esc(t('dy-legend-parent', 'parent and child, siblings, other'))}</span><span>- - ${esc(t('dy-legend-spouse', 'married'))}</span><span>▭ ${esc(t('dy-legend-out', 'dashed box: no elected office in Bukidnon on record'))}</span></p>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-members', 'Members and offices'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr><th scope="col">${esc(t('dy-col-name', 'Name'))}</th><th scope="col">${esc(t('dy-col-offices', 'Elected offices'))}</th></tr></thead>
          <tbody>${members}</tbody></table></div>
      </section>
      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-ties-sources', 'Ties and sources'))}</h2>
        <ul class="dy-ties">${fam.ties.map((tie) => tieItem(fam, tie)).join('')}</ul>
      </section>`;
  }

  // Layered family diagram: parents above children, spouses and siblings side by side.
  function diagram(fam) {
    const gen = {};
    const keys = fam.members.map((m) => m.key);
    gen[keys[0]] = 0;
    const UP = new Set(['father', 'mother', 'parent', 'father-in-law', 'mother-in-law', 'uncle', 'aunt']);
    const DOWN = new Set(['son', 'daughter', 'child', 'son-in-law', 'daughter-in-law', 'nephew', 'niece']);
    const UP2 = new Set(['grandfather', 'grandmother']);
    const DOWN2 = new Set(['grandson', 'granddaughter']);
    const delta = (role) => (UP.has(role) ? -1 : DOWN.has(role) ? 1 : UP2.has(role) ? -2 : DOWN2.has(role) ? 2 : 0);
    for (let pass = 0; pass < keys.length + 1; pass++) {
      for (const tie of fam.ties) {
        // aIs describes A relative to B: A "father" → A is one generation above B
        if (gen[tie.a] != null && gen[tie.b] == null) gen[tie.b] = gen[tie.a] - delta(tie.aIs);
        else if (gen[tie.b] != null && gen[tie.a] == null) gen[tie.a] = gen[tie.b] + delta(tie.aIs);
      }
      for (const k of keys) if (gen[k] == null && pass === keys.length) gen[k] = 0;
    }
    const min = Math.min(...keys.map((k) => gen[k] ?? 0));
    const rows = [];
    // Within a row, keep people tied to each other (spouses, siblings) side by side:
    // walk each same-row group from its first member before moving on.
    const sameRow = (k) => fam.ties.filter((t) => (t.a === k || t.b === k) && gen[t.a] === gen[t.b]).map((t) => (t.a === k ? t.b : t.a));
    const placed = new Set();
    for (const start of keys) {
      if (placed.has(start)) continue;
      const stack = [start];
      while (stack.length) {
        const k = stack.shift();
        if (placed.has(k)) continue;
        placed.add(k);
        (rows[(gen[k] ?? 0) - min] ??= []).push(k);
        stack.unshift(...sameRow(k).filter((x) => !placed.has(x)));
      }
    }
    const W = 200;
    const H = 50;
    const GX = 70;
    const GY = 64;
    const width = Math.max(...rows.map((r) => r?.length ?? 0)) * (W + GX) + GX;
    const pos = {};
    rows.forEach((r, ri) => {
      const rowW = r.length * (W + GX) - GX;
      const x0 = (width - rowW) / 2;
      r.forEach((k, i) => (pos[k] = { x: x0 + i * (W + GX), y: 10 + ri * (H + GY) }));
    });
    const height = rows.length * (H + GY) - GY + 60; // room for arcs under the last row
    const edges = fam.ties
      .map((tie) => {
        const a = pos[tie.a];
        const b = pos[tie.b];
        if (!a || !b) return '';
        const spouse = ['husband', 'wife', 'spouse'].includes(tie.aIs);
        let d;
        let lx;
        let ly;
        let label;
        let anchor = 'middle';
        if (a.y === b.y) {
          const [l, r] = a.x < b.x ? [a, b] : [b, a];
          if (r.x - l.x <= W + GX) {
            d = `M${l.x + W} ${l.y + H / 2} L${r.x} ${r.y + H / 2}`;
            ly = l.y + H / 2 - 5;
          } else {
            // Not neighbours: arc under the boxes instead of running behind them
            const y0 = l.y + H;
            d = `M${l.x + W / 2} ${y0} C${l.x + W / 2} ${y0 + 34}, ${r.x + W / 2} ${y0 + 34}, ${r.x + W / 2} ${y0}`;
            ly = y0 + 34;
          }
          lx = (l.x + r.x + W) / 2;
          label = spouse ? t('dy-legend-spouse', 'married') : roleLabel(tie.aIs).toLowerCase();
        } else {
          const [top, bot] = a.y < b.y ? [a, b] : [b, a];
          const my = top.y + H + GY / 2;
          d = `M${top.x + W / 2} ${top.y + H} L${top.x + W / 2} ${my} L${bot.x + W / 2} ${my} L${bot.x + W / 2} ${bot.y}`;
          // Label the lower person's role next to their line ("son", "nephew")
          label = roleLabel(bot === b ? tie.bIs : tie.aIs).toLowerCase();
          lx = bot.x + W / 2 + 5;
          ly = bot.y - 7;
          anchor = 'start';
        }
        return `<path class="dy-edge${spouse ? ' dy-edge-spouse' : ''}" d="${d}"/><text class="dy-edge-label" x="${lx}" y="${ly}" text-anchor="${anchor}">${esc(label)}</text>`;
      })
      .join('');
    const nodes = fam.members
      .map((m) => {
        const p = pos[m.key];
        const name = m.person ? idx.person[m.person]?.name ?? m.name : m.name;
        const office = m.person ? (officeLines(m.person)[0] ?? '') : (m.offices ?? [])[0] ?? '';
        const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
        const inner = `<rect x="${p.x}" y="${p.y}" width="${W}" height="${H}"/>
          <text class="dy-node-name" x="${p.x + 10}" y="${p.y + 20}">${esc(short(name, 28))}</text>
          <text class="dy-node-office" x="${p.x + 10}" y="${p.y + 37}">${esc(short(office, 34))}</text>`;
        const isOut = !m.person;
        return `<g class="dy-node${isOut ? ' dy-node-out' : ''}">${m.person ? `<a href="#/person/${esc(m.person)}">${inner}</a>` : inner}</g>`;
      })
      .join('');
    return `<svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(t('dy-diagram', 'How they are related'))}">${edges}${nodes}</svg>`;
  }

  // ---------- Views: Officials ----------

  const PAGE = 50;
  let page = 1;

  function renderOfficials() {
    const q = fold($('#o-search').value.trim());
    const pos = $('#o-position').value;
    const place = $('#o-place').value;
    const onlyTied = $('#o-tied').checked;
    const list = D.people.filter((p) => {
      if (q && !fold(p.name).includes(q) && !p.ballots.some((b) => fold(b).includes(q))) return false;
      if (onlyTied && !idx.tiesOf[p.id]?.length) return false;
      const tms = idx.termsOf[p.id] ?? [];
      if (pos && !tms.some((tm) => tm.position === pos)) return false;
      if (place && !tms.some((tm) => tm.place === place)) return false;
      return true;
    });
    list.sort((a, b) => a.last.localeCompare(b.last) || a.name.localeCompare(b.name));
    const pages = Math.max(1, Math.ceil(list.length / PAGE));
    page = Math.min(page, pages);
    $('#o-count').textContent = t('dy-n-results', '{n} officials', { n: list.length.toLocaleString() });
    $('#o-results').innerHTML = list
      .slice((page - 1) * PAGE, page * PAGE)
      .map((p) => {
        const fams = [...(idx.familiesOf[p.id] ?? [])];
        return `<li><span>${personLink(p.id)}</span><span class="dy-chips">${fams.map(familyChip).join('')}</span>
          <p class="dy-sub">${esc(officeLines(p.id).join(' · '))}</p></li>`;
      })
      .join('');
    pager(pages);
  }

  function pager(pages) {
    const nav = $('#o-pager');
    if (pages <= 1) return (nav.innerHTML = '');
    const btn = (n, label = n, current = false, disabled = false) =>
      `<button type="button" data-page="${n}" ${current ? 'aria-current="page"' : ''} ${disabled ? 'disabled' : ''}>${label}</button>`;
    const nums = [];
    for (let n = 1; n <= pages; n++) {
      if (n === 1 || n === pages || Math.abs(n - page) <= 1) nums.push(btn(n, n, n === page));
      else if (nums.at(-1) !== '<span>…</span>') nums.push('<span>…</span>');
    }
    nav.innerHTML = btn(page - 1, '‹', false, page === 1) + nums.join('') + btn(page + 1, '›', false, page === pages);
  }

  // ---------- Views: Person ----------

  function renderPerson(id) {
    const p = idx.person[id];
    if (!p) return notFound();
    const tms = (idx.termsOf[id] ?? []).slice().sort((a, b) => b.year - a.year);
    const termRows = tms
      .map(
        (tm) => `<tr>
          <td class="dy-year">${tm.year}–${tm.year + TERM}</td>
          <td>${esc(posLabel(tm.position))}</td>
          <td>${tm.place ? `<a href="#/place/${tm.place}">${esc(placeName(tm.place))}</a>` : tm.placeCandidates ? esc(tm.placeCandidates.map(placeName).join(' or ')) : esc(t('dy-province-wide', 'Bukidnon'))}</td>
          <td class="dy-hide-sm">${esc(tm.party ?? '')}</td>
          <td class="dy-hide-sm"><span class="dy-sub" style="margin:0">${esc(tm.ballot)}</span></td>
        </tr>`,
      )
      .join('');
    const fixes = [...new Set(tms.filter((tm) => tm.fix).map((tm) => tm.fix))];

    const ties = idx.tiesOf[id] ?? [];
    const tieHtml = ties.length
      ? `<ul class="dy-ties">${ties
          .map(({ fam, tie, other, role }) => {
            const om = fam.members.find((m) => m.key === other);
            const who = om?.person ? personLink(om.person) : `<strong>${esc(om?.name ?? other)}</strong>`;
            const offices = om?.person ? officeLines(om.person) : om?.offices ?? [];
            return `<li>
              <span class="dy-tie-role">${esc(roleLabel(role))}</span>
              <span class="dy-tie-who">${who} <a class="dy-chip" href="#/family/${esc(fam.id)}" style="margin-left:6px">${esc(fam.name)}</a></span>
              ${offices.length ? `<span class="dy-tie-offices">${esc(offices.join(' · '))}</span>` : ''}
              ${tie.note ? `<p class="dy-note">${esc(tie.note)}</p>` : ''}
              ${sourcesHtml(tie.sources)}
            </li>`;
          })
          .join('')}</ul>`
      : `<p class="dy-none">${esc(t('dy-no-ties-person', 'No family ties documented yet. If you know of one with a published source, report it.'))}</p>`;

    // Same surname elsewhere in Bukidnon offices, excluding documented relatives
    const relIds = new Set(ties.map((x) => x.fam.members.find((m) => m.key === x.other)?.person).filter(Boolean));
    const peers = D.people.filter((o) => o.id !== id && fold(o.last) === fold(p.last) && !relIds.has(o.id));

    $('#person-body').innerHTML = `
      <p class="dy-crumbs"><a href="#/officials">${esc(t('dy-nav-officials', 'All officials'))}</a></p>
      <h1 class="dy-h1">${esc(p.name)}</h1>
      <p class="dy-lede">${esc(officeLines(id).join(' · '))}</p>

      <section class="dy-block" style="margin-top:28px">
        <h2 class="dy-section-h">${esc(t('dy-relatives', 'Documented relatives in elected office'))}</h2>
        ${tieHtml}
      </section>

      <section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-offices-held', 'Elected offices in Bukidnon, 2001–2025'))}</h2>
        <div class="dy-table-wrap"><table class="dy-table">
          <thead><tr>
            <th scope="col">${esc(t('dy-col-term', 'Term'))}</th>
            <th scope="col">${esc(t('dy-position', 'Office'))}</th>
            <th scope="col">${esc(t('dy-place', 'Place'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-col-party', 'Party'))}</th>
            <th scope="col" class="dy-hide-sm">${esc(t('dy-col-ballot', 'Name in the source'))}</th>
          </tr></thead>
          <tbody>${termRows}</tbody></table></div>
        ${p.mergeNote ? `<p class="dy-note dy-note-plain">${esc(t('dy-merge-note', 'Treated as one person:'))} ${esc(p.mergeNote)}</p>` : ''}
        ${fixes.map((f) => `<p class="dy-note">${esc(t('dy-fix-note', 'Corrected:'))} ${esc(idx.fix[f].reason)}</p>`).join('')}
      </section>

      ${
        peers.length
          ? `<section class="dy-block">
        <h2 class="dy-section-h">${esc(t('dy-same-surname', 'Same surname, relationship not documented'))}</h2>
        <p class="dy-block-sub">${esc(t('dy-same-surname-note', 'Other Bukidnon officials named {last}. A shared surname is not evidence of kinship.', { last: p.last }))}</p>
        <div class="dy-councils">${peers.map((o) => `<span>${personLink(o.id)} <span class="dy-count">${esc(officeLines(o.id)[0] ?? '')}</span></span>`).join('')}</div>
      </section>`
          : ''
      }`;
  }

  // ---------- Views: About ----------

  function renderAbout() {
    const unplaced = D.terms.filter((tm) => !tm.place && !['governor', 'vice-governor', 'representative', 'board-member'].includes(tm.position));
    $('#about-body').innerHTML = `
      <h1 class="dy-h1">${esc(t('dy-nav-about', 'About the data'))}</h1>
      <div class="dy-prose" style="margin-top:16px">
        <h2 class="dy-section-h">${esc(t('dy-about-what-h', 'What is here'))}</h2>
        <p>${esc(t('dy-about-what', 'Every winner of a seat elected in Bukidnon from 2001 to 2025: governor, vice governor, House representatives, provincial board members, and the mayors, vice mayors and councilors of the 2 cities and 20 municipalities. On top of that, the family ties between them that a published source states.'))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-elections-h', 'Election results'))}</h2>
        <p>${esc(t('dy-about-elections', 'Winners come from OpenHalalan, a volunteer-run dataset of Philippine national and local elections, licensed under the Open Database License (ODbL 1.0). Our cleaned copy, officials.json, is published under the same license.'))}</p>
        <p class="dy-sub" style="font-size:12px">${esc(D.source.citation)} ${extLink(D.source.doi, D.source.doi)}</p>
        <p>${esc(t('dy-about-matching', 'The source has one row per person per election. We match rows to the same person by surname and given names, ignoring accents and initials. Where a ballot nickname differs from the full name, an editor matches them by hand and the person page says so. Two people with the same name can still be merged by mistake; report it if you see one.'))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-ties-h', 'Family ties'))}</h2>
        <p>${esc(t('dy-about-ties', 'A tie is listed only when a news report, official page or other published source states it, and every tie links to that source. We do not infer kinship from shared surnames; where officials share a surname without a documented tie, the person page says so plainly. Being related is not wrongdoing.'))}</p>
        <p>${esc(F.note)}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-fixes-h', 'Corrections to the source'))}</h2>
        <p>${esc(t('dy-about-fixes', 'We found errors in the source rows for Bukidnon and reported them to OpenHalalan.'))} ${extLink('https://github.com/RobertRLeung/OpenHalalan/issues/5', 'OpenHalalan #5')}</p>
        <ul>${D.fixes.map((f) => `<li>${esc(f.reason)}</li>`).join('')}</ul>
        <p>${esc(t('dy-about-gaps', 'Races with no winners in the source:'))} ${esc(
          [...new Set(D.gaps.map((g) => `${placeName(g.place)} ${g.year}`))].join(', '),
        )}.</p>
        <p>${esc(t('dy-about-unplaced', '{n} councilor and vice mayor terms are filed under the wrong place and could not be placed with certainty; they are shown on both possible places.', { n: unplaced.length }))}</p>

        <h2 class="dy-section-h">${esc(t('dy-about-correct-h', 'Report a correction'))}</h2>
        <p>${esc(t('dy-about-correct', 'If something is wrong or missing, open an issue on GitHub or email us, and include a link to a published source.'))}
          ${extLink('https://github.com/Better-Bukidnon/dynasties/issues/new', 'GitHub')} · <a href="mailto:volunteer@betterbukidnon.org">volunteer@betterbukidnon.org</a></p>
      </div>`;
  }

  function notFound() {
    show('about');
    $('#about-body').innerHTML = `<p class="dy-empty">${esc(t('dy-not-found', 'That page does not exist.'))} <a href="#/">${esc(t('dy-nav-mayors', 'Mayors'))}</a></p>`;
  }

  // ---------- Router ----------

  function show(view, nav = view) {
    for (const s of document.querySelectorAll('.dy-view')) s.hidden = s.dataset.view !== view;
    for (const a of document.querySelectorAll('.dy-subnav a')) {
      if (a.dataset.nav === nav) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    }
  }

  function route() {
    const [, view = '', arg] = (location.hash || '#/').split('/');
    const go = {
      '': () => (show('mayors'), renderMayors()),
      mayors: () => (show('mayors'), renderMayors()),
      place: () => (show('place', 'mayors'), renderPlace(decodeURIComponent(arg ?? ''))),
      province: () => (show('province'), renderProvince()),
      families: () => (show('families'), renderFamilies()),
      family: () => (show('family', 'families'), renderFamily(decodeURIComponent(arg ?? ''))),
      officials: () => (show('officials'), renderOfficials()),
      person: () => (show('person', 'officials'), renderPerson(decodeURIComponent(arg ?? ''))),
      about: () => (show('about'), renderAbout()),
    }[view];
    (go ?? notFound)();
  }

  function fillSelects() {
    const dist = $('#m-district');
    for (const d of [...new Set(D.places.map((p) => p.district))]) dist.insertAdjacentHTML('beforeend', `<option value="${d}">${esc(t('dy-district-n', '{d} district', { d }))}</option>`);
    const pos = $('#o-position');
    for (const p of D.positions) pos.insertAdjacentHTML('beforeend', `<option value="${p}">${esc(posLabel(p))}</option>`);
    const pl = $('#o-place');
    for (const p of D.places) pl.insertAdjacentHTML('beforeend', `<option value="${p.id}">${esc(p.name)}</option>`);
  }

  async function init() {
    const today = $('#today');
    if (today) today.textContent = new Date().toLocaleDateString('en-PH', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    try {
      [D, F] = await Promise.all(['data/officials.json', 'data/families.json'].map((u) => fetch(u).then((r) => (r.ok ? r.json() : Promise.reject(new Error(u))))));
    } catch (e) {
      $('#loading').textContent = t('dy-load-failed', 'Could not load the data. Please reload the page.');
      return;
    }
    $('#loading').hidden = true;
    buildIndex();
    fillSelects();
    const built = new Date(D.generatedAt).toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
    $('#built').textContent = ` · ${t('dy-built', 'Built {when}', { when: built })} · ${t('dy-ties-updated', 'ties reviewed {when}', { when: F.updated })}`;

    for (const id of ['m-search', 'm-district', 'm-tied']) $('#' + id).addEventListener('input', renderMayors);
    for (const id of ['o-search', 'o-position', 'o-place', 'o-tied'])
      $('#' + id).addEventListener('input', () => {
        page = 1;
        renderOfficials();
      });
    $('#o-pager').addEventListener('click', (e) => {
      const b = e.target.closest('button[data-page]');
      if (!b || b.disabled) return;
      page = Number(b.dataset.page);
      renderOfficials();
      $('#o-results').scrollIntoView({ block: 'start' });
    });
    window.addEventListener('hashchange', () => {
      route();
      if (!location.hash.startsWith('#/officials')) window.scrollTo(0, 0);
    });
    I18N?.onChange(() => {
      fillSelectsLabels();
      route();
    });
    route();
  }

  function fillSelectsLabels() {
    for (const o of $('#m-district').options) if (o.value) o.textContent = t('dy-district-n', '{d} district', { d: o.value });
    for (const o of $('#o-position').options) if (o.value) o.textContent = posLabel(o.value);
  }

  init();
})();
